l=B.t9(f)/$.x2[1]
e=B.bf3(l)
k=0.725/B.Oi(l,0.2)
j=[B.Oi(m*q[0]*b/100,0.42),B.Oi(m*q[1]*a/100,0.42),B.Oi(m*q[2]*a0/100,0.42)]
d=j[0]
